import { test, expect, Page } from '@playwright/test';

test.describe('Task Creation Form', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should create a new task with all required fields filled', async () => {
    // Click on the "Create Task" button
    const createTaskButton = page.getByRole('button', { name: /create task/i });
    await createTaskButton.click();

    // Wait for the form to appear
    const taskForm = page.getByRole('form');
    await expect(taskForm).toBeVisible();

    // Fill in the task title
    const titleInput = page.getByLabel(/task title/i);
    await titleInput.fill('Complete project documentation');

    // Fill in the task description
    const descriptionInput = page.getByLabel(/task description/i);
    await descriptionInput.fill('Write comprehensive documentation for the new API endpoints');

    // Select priority from dropdown
    const prioritySelect = page.getByLabel(/priority/i);
    await prioritySelect.selectOption('high');

    // Select due date
    const dueDateInput = page.getByLabel(/due date/i);
    await dueDateInput.fill('2024-12-31');

    // Select assignee
    const assigneeSelect = page.getByLabel(/assignee/i);
    await assigneeSelect.selectOption('john.doe@example.com');

    // Click the Save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/task created successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the new task appears in the task list
    const taskItem = page.getByText(/Complete project documentation/i);
    await expect(taskItem).toBeVisible();
  });

  test('should display validation errors when required fields are empty', async () => {
    // Click on the "Create Task" button
    const createTaskButton = page.getByRole('button', { name: /create task/i });
    await createTaskButton.click();

    // Wait for the form to appear
    const taskForm = page.getByRole('form');
    await expect(taskForm).toBeVisible();

    // Try to save without filling any fields
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify error messages appear for required fields
    const titleError = page.getByText(/title is required/i);
    await expect(titleError).toBeVisible();

    const descriptionError = page.getByText(/description is required/i);
    await expect(descriptionError).toBeVisible();

    const priorityError = page.getByText(/priority is required/i);
    await expect(priorityError).toBeVisible();
  });

  test('should create a task with only required fields and optional fields empty', async () => {
    // Click on the "Create Task" button
    const createTaskButton = page.getByRole('button', { name: /create task/i });
    await createTaskButton.click();

    // Wait for the form to appear
    const taskForm = page.getByRole('form');
    await expect(taskForm).toBeVisible();

    // Fill in only required fields
    const titleInput = page.getByLabel(/task title/i);
    await titleInput.fill('Quick bug fix');

    const descriptionInput = page.getByLabel(/task description/i);
    await descriptionInput.fill('Fix login page styling issue');

    const prioritySelect = page.getByLabel(/priority/i);
    await prioritySelect.selectOption('medium');

    // Leave optional fields (due date, assignee) empty
    // Click the Save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/task created successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the new task appears in the task list
    const taskItem = page.getByText(/Quick bug fix/i);
    await expect(taskItem).toBeVisible();
  });

  test('should cancel task creation and return to task list', async () => {
    // Click on the "Create Task" button
    const createTaskButton = page.getByRole('button', { name: /create task/i });
    await createTaskButton.click();

    // Wait for the form to appear
    const taskForm = page.getByRole('form');
    await expect(taskForm).toBeVisible();

    // Fill in some fields
    const titleInput = page.getByLabel(/task title/i);
    await titleInput.fill('Task to cancel');

    // Click the Cancel button
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await cancelButton.click();

    // Verify the form is closed
    await expect(taskForm).not.toBeVisible();

    // Verify the task was not created
    const taskItem = page.getByText(/Task to cancel/i);
    await expect(taskItem).not.toBeVisible();
  });

  test('should handle special characters in task fields', async () => {
    // Click on the "Create Task" button
    const createTaskButton = page.getByRole('button', { name: /create task/i });
    await createTaskButton.click();

    // Wait for the form to appear
    const taskForm = page.getByRole('form');
    await expect(taskForm).toBeVisible();

    // Fill in fields with special characters
    const titleInput = page.getByLabel(/task title/i);
    await titleInput.fill('Task with special chars: @#$%^&*()');

    const descriptionInput = page.getByLabel(/task description/i);
    await descriptionInput.fill('Description with "quotes" and \'apostrophes\' & ampersands');

    const prioritySelect = page.getByLabel(/priority/i);
    await prioritySelect.selectOption('low');

    // Click the Save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/task created successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the task with special characters appears correctly
    const taskItem = page.getByText(/Task with special chars: @#\$%\^&\*\(\)/);
    await expect(taskItem).toBeVisible();
  });
});
